require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');csrf_check();$id=(int)($_POST['id_kegiatan']??0);if(empty($_FILES['file_excel']['tmp_name'])){flash('danger','Pilih file Excel terlebih dahulu.');redirect('/admin/petugas/index.php?id='.$id);} $file=$_FILES['file_excel'];if($file['error']!==UPLOAD_ERR_OK||$file['size']>5*1024*1024){flash('danger','Upload gagal atau ukuran file melebihi 5 MB.');redirect('/admin/petugas/index.php?id='.$id);} $ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));$rows=[];
if($ext==='csv'){$h=fopen($file['tmp_name'],'r');while(($r=fgetcsv($h,0,','))!==false)$rows[]=$r;fclose($h);}elseif($ext==='xlsx'&&class_exists('ZipArchive')){$z=new ZipArchive();if($z->open($file['tmp_name'])!==true){flash('danger','File XLSX tidak dapat dibaca.');redirect('/admin/petugas/index.php?id='.$id);} $xml=$z->getFromName('xl/worksheets/sheet1.xml');$shared=$z->getFromName('xl/sharedStrings.xml');$strings=[];if($shared){preg_match_all('/<si[^>]*>(.*?)<\/si>/s',$shared,$sm);foreach($sm[1] as $si){preg_match_all('/<t[^>]*>(.*?)<\/t>/s',$si,$tm);$strings[]=html_entity_decode(implode('', $tm[1]),ENT_QUOTES|ENT_XML1,'UTF-8');}}if(!$xml){$z->close();flash('danger','Sheet pertama tidak ditemukan.');redirect('/admin/petugas/index.php?id='.$id);}preg_match_all('/<row\b[^>]*>(.*?)<\/row>/s',$xml,$rm);foreach($rm[1] as $rowXml){$row=[];preg_match_all('/<c\b([^>]*)>(.*?)<\/c>/s',$rowXml,$cm,PREG_SET_ORDER);foreach($cm as $cell){preg_match('/\br="([A-Z]+)\d+"/',$cell[1],$ref);$col=$ref[1]??'A';$idx=0;foreach(str_split($col) as $ch)$idx=$idx*26+ord($ch)-64;$idx--;$val='';if(preg_match('/\bt="s"/',$cell[1])&&preg_match('/<v>(\d+)<\/v>/',$cell[2],$vm))$val=$strings[(int)$vm[1]]??'';elseif(preg_match('/<t[^>]*>(.*?)<\/t>/s',$cell[2],$vm))$val=html_entity_decode($vm[1],ENT_QUOTES|ENT_XML1,'UTF-8');elseif(preg_match('/<v>(.*?)<\/v>/s',$cell[2],$vm))$val=html_entity_decode($vm[1],ENT_QUOTES|ENT_XML1,'UTF-8');$row[$idx]=$val;}if($row)$rows[]=$row;}$z->close();}else{flash('danger','Format harus .xlsx atau .csv. Untuk XLSX, aktifkan ekstensi ZipArchive di XAMPP.');redirect('/admin/petugas/index.php?id='.$id);}
if(count($rows)<2){flash('danger','File tidak berisi data petugas.');redirect('/admin/petugas/index.php?id='.$id);} $header=array_map(fn($v)=>strtolower(trim((string)$v)),array_shift($rows));$nameIdx=array_search('nama petugas',$header,true);$kcIdx=array_search('kecamatan',$header,true);if($nameIdx===false||$kcIdx===false){flash('danger','Kolom wajib Nama Petugas dan Kecamatan tidak ditemukan.');redirect('/admin/petugas/index.php?id='.$id);} $valid=[];$errors=[];$seen=[];foreach($rows as $i=>$r){$line=$i+2;$name=trim((string)($r[$nameIdx]??''));$kc=strtoupper(trim((string)($r[$kcIdx]??'')));if($name===''&&$kc==='')continue;if($name===''||!in_array($kc,kecamatan_list(),true)){$errors[]="Baris {$line}: nama kosong atau kecamatan tidak sesuai referensi.";continue;}$key=strtolower($name);if(isset($seen[$key])){$errors[]="Baris {$line}: nama petugas duplikat di file.";continue;}$seen[$key]=true;$valid[]=['nama_petugas'=>$name,'kecamatan'=>$kc,'baris'=>$line];}
$exists=$pdo->prepare('SELECT nama_petugas FROM petugas WHERE id_kegiatan=? AND deleted_at IS NULL');$exists->execute([$id]);$names=array_map(fn($r)=>strtolower($r['nama_petugas']),$exists->fetchAll());foreach($valid as $v)if(in_array(strtolower($v['nama_petugas']),$names,true))$errors[]='Baris '.$v['baris'].': '.$v['nama_petugas'].' sudah terdaftar pada kegiatan ini.';
$_SESSION['petugas_import']=['id_kegiatan'=>$id,'rows'=>$valid,'errors'=>$errors];redirect('/admin/petugas/preview.php');
